declare(strict_types=1);require __DIR__.'/../lib/bootstrap.php';require_once CM_LIB.'/view.php';require_once CM_LIB.'/register.php';require_once CM_LIB.'/clients.php';require_once CM_LIB.'/format.php';$admin=cm_require_admin();cm_schema_gate('register','register');$id=(int)($_GET['id']??0);$sale=cm_register_sale($id);if(!$sale){http_response_code(404);exit('Receipt not found.');}$refundError='';if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){cm_require_csrf();$refundError=cm_register_refund($id,(string)($_POST['amount']??''),(string)($_POST['reason']??''),(string)($_POST['refund_method']??''),(string)$admin['email']);if($refundError===''){cm_flash('Refund recorded. The original sale was not changed.');cm_redirect('admin/register-receipt.php?id='.$id);}$sale=cm_register_sale($id);}$refunds=cm_all('SELECT * FROM register_refund WHERE sale_id=? ORDER BY created_at',[$id]);$remaining=(int)$sale['total_cents']-(int)$sale['refunded_cents'];$business=(string)cm_setting('business.name',(string)cm_setting('mail.from_name','Client Work Hub'));cm_head('Receipt '.(string)$sale['receipt_no'],'',true);cm_render_flashes();cm_admin_nav('register');?>
<div class="topbar no-print"><div><?=cm_crumbs_html([['label'=>'Cash register','href'=>cm_url('admin/register.php')],['label'=>(string)$sale['receipt_no']]])?><h1>Receipt</h1></div><div class="actions"><button class="btn btn-quiet" type="button" data-print>Print receipt</button><a class="btn" href="<?=e(cm_url('admin/register.php'))?>">New sale</a></div></div>
<article class="card receipt"><div class="receipt-head"><div><p class="eyebrow"><?=e($business)?></p><h2><?=e((string)$sale['receipt_no'])?></h2></div><div class="text-right"><b><?=e(date('j F Y, g:ia',strtotime((string)$sale['created_at'])))?></b><div><?=e(cm_register_status($sale))?></div></div></div><hr><div class="summary-strip"><div><span class="summary-k">Customer</span><b><?=$sale['client_id']?e(cm_client_display_name($sale)):'Walk-in'?></b></div><div><span class="summary-k">Payment</span><b><?=e(cm_register_methods()[(string)$sale['payment_method']]??'Other')?></b></div><div><span class="summary-k">Total</span><b><?=e(cm_money((int)$sale['total_cents']))?></b></div></div><?php if((string)$sale['description']!==''):?><p class="mt-16"><b>Description</b><br><?=e((string)$sale['description'])?></p><?php endif;?><?php if((string)$sale['payment_method']==='cash'):?><div class="summary-strip mt-16"><div><span class="summary-k">Cash received</span><b><?=e(cm_money((int)$sale['amount_received_cents']))?></b></div><div><span class="summary-k">Change</span><b><?=e(cm_money((int)$sale['change_cents']))?></b></div></div><?php endif;?>
<?php if($refunds):?><hr><h3>Refunds</h3><?php foreach($refunds as$r):?><div class="summary-line"><span><?=e(date('j M Y, g:ia',strtotime((string)$r['created_at'])))?> · <?=e(cm_register_methods()[(string)$r['refund_method']]??'Other')?> · <?=e((string)$r['reason'])?></span><b>−<?=e(cm_money((int)$r['amount_cents']))?></b></div><?php endforeach;?><div class="summary-line"><span>Net received</span><strong><?=e(cm_money($remaining))?></strong></div><?php endif;?><p class="muted small mt-24">Thank you. This receipt records a completed transaction.</p></article>
<?php if($remaining>0):?><div class="card mt-16 no-print"><h2>Refund</h2><p class="muted small">Refunds are separate records. The original sale and receipt are never edited or deleted.</p><?php if($refundError!==''):?><div class="note note-error"><?=e($refundError)?></div><?php endif;?><form method="post" data-confirm="Record this refund? It cannot be deleted from the transaction history."><?=cm_csrf_field()?><div class="form-2col"><div class="form-col"><div class="row"><label class="lbl">Amount</label><input name="amount" inputmode="decimal" value="<?=e(number_format($remaining/100,2,'.',''))?>" required></div></div><div class="form-col"><div class="row"><label class="lbl">Refund method</label><select name="refund_method"><?php foreach(cm_register_methods()as$k=>$v):?><option value="<?=e($k)?>"<?=$k===(string)$sale['payment_method']?' selected':''?>><?=e($v)?></option><?php endforeach;?></select></div></div></div><div class="row"><label class="lbl">Reason</label><input name="reason" maxlength="255" required></div><button class="btn btn-quiet" type="submit">Record refund</button></form></div><?php endif;?><script defer src="<?=e(cm_url('js/register.js'))?>?v=<?=e(rawurlencode(cm_asset_stamp()))?>"></script><?php cm_foot();?>
